using UnityEngine;
using UnityEngine.Rendering;
namespace BWVR {
public sealed partial class GodToolPalette {
 public TerrainSculptor Sculptor{get;private set;}
 GameObject sculptGhost;Mesh sculptMesh;Material sculptMaterial;bool sculptHeld,sculptLocked;Vector3 sculptAnchor;float sculptBegan;SliceState sculptSeason;SpiritualTool sculptMode;
 public float SculptCharge=>sculptHeld?Mathf.Clamp01((Season.Hybrid.time-sculptBegan)/TerrainSculptor.ChargeSeconds):0;
 void BuildSculpt(){Sculptor=nav.GetComponentInChildren<TerrainSculptor>();if(Sculptor!=null)Sculptor.Applied+=()=>{Uses++;feedback?.Invoke(true,"Ground reshaped");};sculptGhost=new GameObject("Proposed sculpted surface",typeof(MeshFilter),typeof(MeshRenderer));sculptGhost.transform.SetParent(transform,false);sculptMesh=new Mesh{name="Bounded terrain preview"};sculptGhost.GetComponent<MeshFilter>().sharedMesh=sculptMesh;sculptMaterial=new Material(Resources.Load<Shader>("GodToolIcons/TerrainPreview"));sculptMaterial.color=new Color(.3f,.9f,1,.22f);var r=sculptGhost.GetComponent<MeshRenderer>();r.sharedMaterial=sculptMaterial;r.shadowCastingMode=ShadowCastingMode.Off;r.receiveShadows=false;sculptGhost.SetActive(false);}
 void CancelSculpt(){Sculptor?.CancelPending();sculptHeld=false;sculptLocked=false;if(sculptGhost!=null)sculptGhost.SetActive(false);}
 void AimSculpt(Ray ray){bool hit=ground.Raycast(ray,out var contact,8*rig.localScale.x);PreviewPoint=hit?contact.point:ray.GetPoint(2*rig.localScale.x);string why="Aim at clear island ground";PreviewValid=hit&&Sculptor!=null&&Sculptor.CanSculpt(PreviewPoint,Selected.Value,out why);Reason=why;preview.SetActive(hit);preview.transform.position=PreviewPoint;PreviewShape(PreviewValid,TerrainSculptor.Radius);if(PreviewValid){var ring=preview.GetComponent<LineRenderer>();for(int i=0;i<40;i++){float a=i*Mathf.PI/20;var p=PreviewPoint+new Vector3(Mathf.Cos(a),0,Mathf.Sin(a))*nav.Scale*TerrainSculptor.Radius;ring.SetPosition(i,nav.Terrain.Project(p)-PreviewPoint+Vector3.up*nav.Scale*.2f);}}previewMaterial.color=PreviewValid?new Color(.3f,.9f,1):new Color(1,.25f,.18f);DrawSculptPreview();}
 void DrawSculptPreview(){sculptGhost.SetActive(PreviewValid);if(!PreviewValid)return;var data=nav.Terrain;int cx=Mathf.RoundToInt((PreviewPoint.x/data.scale+data.origin.x)/data.cellSize),cz=Mathf.RoundToInt((PreviewPoint.z/data.scale+data.origin.y)/data.cellSize);const int n=9;var v=new Vector3[n*n];var uv=new Vector2[n*n];var tris=new int[(n-1)*(n-1)*6];for(int z=0;z<n;z++)for(int x=0;x<n;x++){var p=data.World(cx+x-4,cz+z-4,0);p=data.Project(p);foreach(var predicted in Sculptor.Preview)if(Mathf.Abs(p.x-predicted.x)<data.scale*.01f&&Mathf.Abs(p.z-predicted.z)<data.scale*.01f){p.y=predicted.y;break;}v[z*n+x]=p+Vector3.up*data.scale*.12f;uv[z*n+x]=new Vector2((x-4)*data.cellSize/TerrainSculptor.Radius,(z-4)*data.cellSize/TerrainSculptor.Radius);}
  int t=0;for(int z=0;z<n-1;z++)for(int x=0;x<n-1;x++){int a=z*n+x,b=a+1,c=a+n,d=c+1;bool split=(data.flags[(cz+z-4)*data.width+cx+x-4]&128)!=0;var cell=split?new[]{a,c,b,b,c,d}:new[]{a,d,b,a,c,d};foreach(var i in cell)tris[t++]=i;}sculptMesh.Clear();sculptMesh.vertices=v;sculptMesh.uv=uv;sculptMesh.triangles=tris;sculptMesh.RecalculateNormals();sculptMesh.RecalculateBounds();}
 public bool ProcessSculpt(Vector3 point,SpiritualTool mode,bool held,bool aimValid){if(sculptSeason!=Season){CancelSculpt();sculptSeason=Season;}if(Season.paused||miracles.Suspended||!TerrainSculptor.IsSculpt(mode)||Sculptor==null){CancelSculpt();return false;}
  if(Sculptor.Pending)return false;
  if(held){if(sculptLocked)return false;if(!aimValid||!Sculptor.CanSculpt(point,mode,out _)){sculptHeld=false;sculptLocked=true;return false;}if(!sculptHeld){sculptHeld=true;sculptAnchor=point;sculptMode=mode;sculptBegan=Season.Hybrid.time;}if(mode!=sculptMode||Vector2.Distance(new Vector2(point.x,point.z),new Vector2(sculptAnchor.x,sculptAnchor.z))>nav.Scale*5||Season.Hybrid.time-sculptBegan>8){sculptHeld=false;sculptLocked=true;}return false;}
  bool ready=sculptHeld&&!sculptLocked&&sculptMode==mode&&SculptCharge>=1&&aimValid&&Vector2.Distance(new Vector2(point.x,point.z),new Vector2(sculptAnchor.x,sculptAnchor.z))<=nav.Scale*5;var at=sculptAnchor;CancelSculpt();if(!ready)return false;bool requested=Sculptor.Request(at,mode);Reason=Sculptor.Reason;if(!requested)feedback?.Invoke(false,Reason);return requested;
 }
 bool SculptPointer(Ray ray,bool pressed){if(!pressed&&sculptHeld)AimSculpt(ray);bool cast=ProcessSculpt(PreviewPoint,Selected.Value,pressed&&!releaseGate,PreviewValid);if(cast)AimSculpt(ray);hint.text=Title(Selected.Value)+" · "+(Sculptor?.Pending==true?"Preparing safe ground":sculptLocked?"Release and aim again":sculptHeld?(SculptCharge>=1?"Release to reshape":"Charging "+Mathf.RoundToInt(SculptCharge*100)+"%"):PreviewValid?"Hold still to charge · release to reshape":Reason);return true;}
 void DisposeSculpt(){if(sculptMesh!=null)Destroy(sculptMesh);if(sculptMaterial!=null)Destroy(sculptMaterial);}
}
}
